mapper.select:
select sl.shop_owner_id shopOwnerId, sl.shop_id shopId, sl.owner_id ownerId, sl.owner_name ownerName,
       sl.link, sl.state, sl.start_time startTime, sl.end_time endTime,
       sl.community_id communityId, sl.status_cd statusCd,
       bs.shop_num shopNum, bs.location_id locationId, sls.location_name locationName
from building_shop_owner sl
left join building_shop bs on sl.shop_id = bs.shop_id and bs.status_cd = '0'
left join shop_location sls on bs.location_id = sls.location_id and sls.status_cd = '0'
where 1 = 1 and sl.status_cd = '0'

    and sl.shop_owner_id = #{shopOwnerId}


    and sl.shop_id = #{shopId}


    and sl.owner_id = #{ownerId}


    and sl.owner_name like concat('%', #{ownerName}, '%')


    and sl.link = #{link}


    and sl.state = #{state}


    and sl.community_id = #{communityId}


    and bs.shop_num like concat('%', #{shopNum}, '%')


    and bs.location_id = #{locationId}

order by sl.create_time desc

    limit #{page}, #{row}

select count(1) count
from building_shop_owner sl
left join building_shop bs on sl.shop_id = bs.shop_id and bs.status_cd = '0'
left join shop_location sls on bs.location_id = sls.location_id and sls.status_cd = '0'
where 1 = 1 and sl.status_cd = '0'

    and sl.shop_owner_id = #{shopOwnerId}


    and sl.shop_id = #{shopId}


    and sl.owner_id = #{ownerId}


    and sl.owner_name like concat('%', #{ownerName}, '%')


    and sl.link = #{link}


    and sl.state = #{state}


    and sl.community_id = #{communityId}


    and bs.shop_num like concat('%', #{shopNum}, '%')


    and bs.location_id = #{locationId}

mapper.update:
update building_shop_owner t set t.status_cd = #{statusCd}

    , t.shop_id = #{shopId}


    , t.owner_id = #{ownerId}


    , t.owner_name = #{ownerName}


    , t.link = #{link}


    , t.state = #{state}


    , t.start_time = #{startTime}


    , t.end_time = #{endTime}

where 1 = 1

    and t.shop_owner_id = #{shopOwnerId}


    and t.shop_id = #{shopId}


    and t.community_id = #{communityId}
